def generate_lucky_numbers(n):
    lucky = []
    def dfs(current):
        if current > n:
            return
        if current > 0:
            lucky.append(current)
        if current * 10 + 4 <= n:
            dfs(current * 10 + 4)
        if current * 10 + 7 <= n:
            dfs(current * 10 + 7)
    dfs(0)
