def parse_components(s):
    n, m = map(int, s.split('\n')[0].split())
    adj = [[] for _ in range(n + 1)]
    for line in s.split('\n')[1:]:
        if line.strip():
            u, v = map(int, line.strip().split())
            adj[u].append(v)
            adj[v].append(u)

    visited = [False] * (n + 1)
    sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            sizes.append(size)

    return sizes, n

def solve():
    sizes, n = parse_components(input())

    if not sizes:
        sizes, n = parse_components(input())

    # Get lucky numbers
    lucky_numbers = generate_lucky_numbers(n)

    # DP to find minimum components needed for each size
    # dp[s] = minimum number of components needed to get total size s
    dp = {}
    dp[0] = 0

    for size in sizes:
        # Iterate in reverse to avoid using same component multiple times
        new_dp = dp.copy()
