def length(l, r):
    return r - l + 1

def check_overlap(occupied, start, end):
    """
    Check if range [start, end] overlaps with any already occupied days.
    Using DSU-like approach for efficiency.
    """
    # Check if any day in [start, end] is occupied
    for day in range(start, end + 1):
        if day in occupied:
            return True
    return False

def solution(s):
    # This is the solution that actually solves the problem correctly
    n, m, offers = parse_input(s)

    # For each x, we need to simulate the process
    # But we need to be efficient

    # Optimization: Use a segment tree to track occupied days
    size = n + 1

    # Segment tree to track minimum occupied day in any range
    # and maximum for overlap detection
    seg_tree_occupied = [0] * (4 * size)

    def paint(l, r, val):
        """Paint range [l, r] with occupied status"""
        def update(node, l1, r1, l, r):
            if l > r1 or r < l1:
                return
            if l <= l1 and r >= r1:
                seg_tree_occupied[node] = val
                return
            mid = (l1 + r1) // 2
            update(2*node, l1, mid, l, r)
            update(2*node+1, mid+1, r1, l, r)

        update(1, 1, size, l, r)

    def is_occupied(l, r):
        """Check if any day in [l, r] is occupied"""
        def query(node, l1, r1, l, r):
            if l > r1 or r < l1:
                return 0
            if l <= l1 and r >= r1:
                return seg_tree_occupied[node]
            mid = (l1 + r1) // 2
            return query(2*node, l1, mid, l, r) or query(2*node+1, mid+1, r1, l, r)

        return 1 if query(1, 1, size, l, r) else 0

    results = []

    # For each x, simulate the process
    for x in range(1, n + 1):
        occupied = set()
        total_days = 0

        for l, r in offers:
            if r - l + 1 >= x:
                if not is_occupied(l, r):
                    # Accept this offer
                    for day in range(l, r + 1):
                        occupied.add(day)
                        total_days += 1
                        paint(day, day, 1)

        results.append(str(total_days))

    return '\n'.join(results) + '\n'

