import os

def solve_grundy(n, k, a):
    if k == 1:
        xor_result = 0
        for val in a:
            xor_result ^= 1 if val % 2 == 1 else 0
    elif k == 2:
        xor_result = 0
        for val in a:
            xor_result ^= [0, 1, 2][val % 3]
    elif k >= 5:
        xor_result = 0
        for val in a:
            xor_result ^= [0, 1, 2][val % 3]
    else:
        memo = {}
        def g(n_val):
            if n_val in memo:
                return memo[n_val]
            can_reach = set()
            can_reach.add(g(n_val - 1))
            if n_val % 2 == 0:
                x = n_val // 2
                can_reach.add(0)  # Even k=4, so 4 copies XOR to 0
            result = 0
            while result in can_reach:
                result += 1
            memo[n_val] = result
            return result

        xor_result = 0
        for val in a:
            xor_result ^= g(val)

    return "Kevin\n" if xor_result != 0 else "Nicky\n"

