    lines = input_string.strip().split('\n')
    n = int(lines[0])
    sequence = list(map(int, lines[1].split()))

    def is_gp(seq):
        """Check if a sequence is a geometric progression."""
        if len(seq) <= 1:
            return True

        # All zeros is always a GP
        if all(x == 0 for x in seq):
            return True

        # Must have at least 2 elements for meaningful check
        # Check for the special case: 0, 0, 0... (already handled above)
        if seq[0] == 0:
            if seq[1] == 0:
                # Remaining must all be 0 (already checked above, but double sure)
                return all(x == 0 for x in seq)
            else:
                # First is 0, second is not - this can only be GP if all elements after second are 0
                # But actually for GP with 0 as first element, all must be 0 (since 0*b = 0)
                return False

        # For non-zero first element
        # In a GP, a[i] * a[i+2] = a[i+1] * a[i+1] for all valid i
        # This is the cross-multiplication form and avoids division

        for i in range(len(seq) - 2):
            left = seq[i] * seq[i + 2]
            right = seq[i + 1] * seq[i + 1]
            if left != right:
                return False

        return True

    # Check if original sequence is GP
    if is_gp(sequence):
        return "0\n"

    # Try removing each element one by one
    for i in range(len(sequence)):
        new_seq = sequence[:i] + sequence[i+1:]
        if is_gp(new_seq):
            return "1\n"

    return "2\n"

