    grid = [list(line) for line in lines[1:]]

    visited = set()
    components = []

    # Find connected components of free cells
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    component.append((curr_r, curr_c))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == '.' and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append(component)

    # For each component, fill its bounding box with free spaces
    result = [list(row) for row in grid]
    for component in components:
        if not component:
            continue
        rows = {r for r, c in component}
        cols = {c for r, c in component}
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        # Mark all cells in the bounding box as free
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if result[r][c] == '*':
                    result[r][c] = '.'

    return '\n'.join(''.join(row) for row in result) + '\n'

