import sys

class Solution:
    def solution(self, input_str):
        lines = input_str.strip().split('\n')
        n, m, k = map(int, lines[0].split())

        # Build adjacency list
        graph = [[] for _ in range(n + 1)]
        for i in range(m):
            u, v = map(int, lines[i + 1].split())
            graph[u].append(v)
            graph[v].append(u)

        # DFS to find cycle with representative
        visited = [0] * (n + 1)
        timestamp = [0]
        parent = [0] * (n + 1)
        cycles = []
        used_representatives = set()

        def dfs(u, start_ts):
            visited[u] = 1
            timestamp[u] = start_ts
            parent[u] = 0

            for v in graph[u]:
                if not visited[v]:
                    parent[v] = u
                    dfs(v, timestamp[u] + 1)
                elif v != parent[u] and timestamp[v] < timestamp[u]:
                    # Back edge, potential cycle
                    # Build cycle from u to v through parents
                    cycle_nodes = [v]
                    curr = u
                    while curr != v:
                        cycle_nodes.append(curr)
                        curr = parent[curr]
                    cycle_nodes.append(curr)  # Complete cycle
                    cycle_nodes.reverse()

                    if len(cycle_nodes) >= 3 and len(cycle_nodes) % 3 != 0:
                        # Find or assign a representative (non-parent vertex in cycle)
                        rep = cycle_nodes[-1]  # Last node before closing
                        cycles.append(cycle_nodes)
                        used_representatives.add(rep)

        # DFS from each vertex
        for start in range(1, n + 1):
            if not visited[start]:
                dfs(start, 1)

        # Check if we found enough cycles
        if len(cycles) >= k:
            result = ["CYCLES"]
            for cyc in cycles[:k]:
                result.append(str(len(cyc)))
                result.append(" ".join(map(str, cyc)))
            return "\n".join(result)

        # Find long path directly
        def find_long_path():
            best_path = []
            for start in range(1, n + 1):
                visited_p = [False] * (n + 1)
                stack = [start]
                visited_p[start] = True
                path = [start]

                while stack and len(path) < min(n, n // k + 2):
                    u = stack.pop()
                    for v in graph[u]:
                        if not visited_p[v]:
                            visited_p[v] = True
                            path.append(v)
                            stack.append(v)
                            break

                if len(path) > len(best_path):
                    best_path = path

            if len(best_path) >= n // k:
                return best_path

        if find_long_path():
            path = find_long_path()
            return f"PATH\n{len(path)}\n{' '.join(map(str, path))}"

        return "[no solution]"

    def __call__(self):
        return Solution()

