import math
from collections import defaultdict

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    adj = defaultdict(list)

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    ceil_sqrt_n = int(math.ceil(math.sqrt(n)))

    # Use BFS to build a BFS tree
    # Then find back edges to detect cycles
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    depth[1] = 0

    while queue and depth[1] < depth[-1]:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                queue.append(v)

    # Now find back edges and check for cycles
    for u in range(1, n + 1):
        for v in adj[u]:
            if v != parent[u] and depth[v] != depth[u] and v > parent[u]:
                if u > parent[u] and v > 0 and depth[v] < depth[u]:
                    # This might be a back edge
                    pass

    # Let's do proper DFS for cycle detection
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)

    def dfs_cycle(u, p):
        visited[u] = True
        parent[u] = p
        depth[u] = depth[p] + 1 if p else 1

        for v in adj[u]:
            if not visited[v]:
                result = dfs_cycle(v, u)
                if result:
                    return result
            elif v != p and depth[v] < depth[u]:
                # Back edge found
                cycle = []
                x = u
                while x != v:
                    cycle.append(x)
                    x = parent[x]
                cycle.append(v)
                if len(cycle) >= ceil_sqrt_n:
                    return cycle
        return None

    # Try DFS from all nodes to find a cycle
    for start in range(1, n + 1):
        visited = [False] * (n + 1)
        result = dfs_cycle(start, None)
        if result:
            if len(result) >= ceil_sqrt_n:
                return f"2\n{len(result)}\n" + " ".join(map(str, result))

    # If no cycle, find independent set using greedy coloring
    color = [0] * (n + 1)

    for i in range(1, n + 1):
        max_c = 0
        for v in adj[i]:
            if color[v] > max_c:
                max_c = color[v]
        color[i] = max_c + 1

    color_counts = defaultdict(int)
    for i in range(1, n + 1):
        color_counts[color[i]] += 1

    best_color = max(color_counts, key=color_counts.get)
    independent_set = [i for i in range(1, n + 1) if color[i] == best_color]

    return f"1\n{len(independent_set)}\n" + " ".join(map(str, independent_set))

