def solution(input_string):
    """
    Count valid permutations with no fixed points where -1 positions
    can be filled with available values.
    """
    input_string = input_string.strip()
    if not input_string:
        return "0"

    lines = input_string.split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Parse permutation
    used_values = set()
    for x in arr:
        if x != -1:
            used_values.add(x)

    # Find positions with -1 and available values
    pos_with_minus = [i for i in range(n) if arr[i] == -1]
    available_values = [x for x in range(1, n + 1) if x not in used_values]

    k = len(pos_with_minus)

    # Use inclusion-exclusion:
    # For each position i with -1, if value (i+1) is available, 
    # placing it creates a fixed point - forbidden
    forbidden_count = sum(1 for i in pos_with_minus if (i + 1) in available_values)

    MOD = 1000000007

    # Precompute factorials
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Inclusion-exclusion: sum(-1)^j * C(forbidden, j) * (k-j)!
    result = 0
    for j in range(forbidden_count + 1):
        sign = 1 if j % 2 == 0 else -1

        # C(forbidden, j) * (k-j)! = forbidden! / j! * (k-j)!
        if j > forbidden_count or j > k:
            continue

        comb = fact[forbidden_count] * pow(fact[j], MOD - 2, MOD) % MOD
        remaining = fact[k - j] if k - j >= 0 else 0
        term = (comb * remaining) % MOD

        if sign == -1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result)

