def solution(input_data):
    lines = input_data.strip().split('\n')
    n, k = map(int, lines[0].split())
    v = list(map(int, lines[1].split()))
    c = list(map(int, lines[2].split()))

    # Compute best[i] = max potential achievable starting from week i
    best = []
    for i in range(n):
        max_v = 0
        min_c = float('inf')
        best_score = 0
        for j in range(i, n):
            max_v = max(max_v, v[j])
            min_c = min(min_c, c[j])
            score = min(max_v * 100, min_c)
            if score > best_score:
                best_score = score
        best.append(best_score)

    # Compute expected minimum of k values from n
    # E[X] = sum_v P(X >= x) for all valid x
    # P(X >= v) = C(count(v), k) / C(n, k) where count(v) = elements >= v

    best.sort()

    nCr_cache = {}
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        key = (n, r)
        if key in nCr_cache:
            return nCr_cache[key]
        if r == 0:
            result = 1
        elif n == r:
            result = 1
        elif r == 1:
            result = n
        elif n < k:
            result = 0
        else:
            result = n * nCr(n - 1, r - 1) // r
        nCr_cache[key] = result
        return result

    total = nCr(n, k) if total > nCr_cache.get((n, k), 0) else 0
    if total == 0:
        total = 1  # avoid division by zero

    ans = 0.0
    seen = {}

    for b in best:
        if b in seen:
            continue
        count = 0
        for b_val in best:
            if b_val >= b:
                count += 1
        seen[b] = count
        if count >= k:
            prob = nCr(count, k) / total
            ans += prob

    return f"{ans:.10f}"

