    for i in range(2, 2 + m):
        part = lines[i].split()
        pos1, t1, pos2, t2 = part[0], part[1], part[2], part[3]
        rules.append((int(pos1), t1, int(pos2), t2))

    # Parse string s
    s = lines[2 + m]

    # Map each character to its type
    types = {}
    for i, ch in enumerate(vowel_consonant):
        types[chr(ord('a') + i)] = ch

    # Check if a word satisfies all rules
    def check(word):
        for pos1, t1, pos2, t2 in rules:
            if types[word[pos1 - 1]] != t1:
                continue  # Rule doesn't apply when condition is false
            if types[word[pos2 - 1]] != t2:
                return False  # Rule violated
        return True

    # Try to find the smallest valid word >= s
    # We start from s and try to increment
    def find_word(current):
        if check(current):
            return current
        # Try to increment the last position
        char_list = list(current)
        # Try changing the last position to a larger character
        for i in range(n - 1, -1, -1):
            # Try to increment char at position i
            old_char = char_list[i]
            # Find next larger character that could potentially work
            # Try each possible character in alphabetical order
            for new_char_ord in range(ord(old_char) + 1, ord('z') + 1):
                new_char = chr(new_char_ord)
                if new_char not in types:
                    continue
                char_list[i] = new_char

                # For positions after i, fill with smallest possible
                for j in range(i + 1, n):
                    # Find smallest valid character at position j
                    min_char = None
                    for c in ['a', 'b', 'c', ...]:
                        if c in types:
                            min_char = c
                            break
                    char_list[j] = min_char

                candidate = ''.join(char_list)
                if check(candidate):
                    return candidate
            char_list[i] = old_char

        return None

    result = find_word(s)
    if result is None:
        return '-1'
    else:
        return result

