            row_rels[q1].add(p1) if s1 == 'R' else row_rels[p1].discard(q1) if q1 != p1 else None

        # T-B edges contribute to column orientation
        if (s1, s2) == ('T', 'B') or (s1, s2) == ('B', 'T'):
            col_rels[p1].add(q1)
            col_rels[q1].add(p1) if s1 == 'B' else col_rels[p1].discard(q1) if q1 != p1 else None

    def build_order_graph(edges_dict, size):
        """Build directed graph for ordering constraints"""
        graph = collections.defaultdict(list)
        visited = [False] * (max_size + 1)

        for pos in range(1, size + 1):
            for neighbor in edges_dict[pos]:
                if neighbor > 0:
                    graph[pos].append(neighbor)

        return graph

    def detect_cycle(graph, n, nodes_to_check):
        """Detect cycle using DFS"""
        visited = [False] * n
        rec_stack = [False] * n

        def dfs(node):
            visited[node] = True
            rec_stack[node] = True
            for neighbor in graph.get(node, []):
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
                elif rec_stack[neighbor]:
                    return True
            rec_stack[node] = False
            return False

        for node in nodes_to_check:
            if not visited[node]:
                if dfs(node):
                    return True
        return False

    # Topological sort for row ordering
    pos = [0] * (n + 1)
    in_degree = [0] * (n + 1)
    adj = collections.defaultdict(list)

    for u in range(1, n + 1):
        for v in row_rels[u]:
            if v > 0 and v <= n:
                adj[u].append(v)
                in_degree[v] += 1

    queue = collections.deque([i for i in range(1, n+1) if in_degree[i] == 0])
    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topo_order) != n:
        return "No solution\n"

