    for u in range(1, m + 1):
        for v in col_rels[u]:
            if v > 0 and v <= m:
                adj2[u].append(v)
                in_degree2[v] += 1

    queue2 = collections.deque([i for i in range(1, m+1) if in_degree2[i] == 0])
    topo_order2 = []
    while queue2:
        u = queue2.popleft()
        topo_order2.append(u)
