    rows = sorted(range(1, n + 1))
    cols = sorted(range(1, m + 1))

    result_rows = []
    result_cols = []

    # Check if mixed edges allow this configuration
    l_edges = collections.defaultdict(list)  # (row, col) = edge info
    r_edges = collections.defaultdict(list)
    t_edges = collections.defaultdict(list)
    b_edges = collections.defaultdict(list)

    for s1, p1, s2, q1 in edges:
        if s1 == 'L':
            l_edges[(p1, q1)].append(s2)
