    Solution for finding the longest common subsequence of s1 and s2
    that doesn't contain virus as a substring.
    """
    lines = input_data.strip().split('\n')
    s1, s2, virus = lines[0], lines[1], lines[2]

    n, m, v_len = len(s1), len(s2), len(virus)

    # Edge case: if no virus, return 0 (empty string)
    if v_len == 0:
        return "0"

    # Compute KMP LPS array for virus
    def compute_lps(p):
        lps = [0] * len(p)
        length = 0
        i = 1
        while i < len(p):
            if p[i] == p[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    lps = compute_lps(virus)

    # KMP transition: new matched length after seeing char
    def get_new_match(k, char):
        while k > 0 and char != virus[k]:
            k = lps[k - 1]
        if char == virus[k]:
            k += 1
        return k

    # DP: dp[i][j][k] = length of LCS of s1[:i] and s2[:j] with virus prefix k
    # parent[i][j][k] = (prev_i, prev_j, prev_k, action) for reconstruction

    dp = [[[0] * (v_len + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    parent = [[[None] * (v_len + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Initialize base case
    dp[0][0][0] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len + 1):
                # Already reachable state
                if dp[i][j][k] < 0:
                    continue

                # Option 1: Skip s1[i-1] - continue to (i+1, j, k)
                if i < n:
                    if dp[i][j][k] < dp[i + 1][j][k]:
                        dp[i + 1][j][k] = dp[i][j][k]
                        parent[i + 1][j][k] = (i, j, k, 'skip1')
                else:
                    break

                # Option 2: Skip s2[j-1] - continue to (i, j+1, k)
                if j < m:
                    if dp[i][j][k] < dp[i][j + 1][k]:
                        dp[i][j + 1][k] = dp[i][j][k]
                        parent[i][j + 1][k] = (i, j, k, 'skip2')
                else:
                    break

            # Option 3: Match characters at s1[i-1] and s2[j-1]
            if i < n and j < m and s1[i] == s2[j]:
                c = s1[i]
                nk = get_new_match(k, c)
                if nk < v_len:
                    # k is current, nk is new virus state after adding character
                    prev_k = k
                    # Try all possible previous virus states
                    for prev_k in range(v_len + 1):
                        if dp[i][j][prev_k] + 1 >= dp[i + 1][j + 1][nk]:
                            if dp[i][j][prev_k] + 1 > dp[i + 1][j + 1][nk]:
                                dp[i + 1][j + 1][nk] = dp[i][j][prev_k] + 1
                                parent[i + 1][j + 1][nk] = (i, j, prev_k, 'match', c)

    # Also fill in remaining positions with skip operations
    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len + 1):
                if dp[i][j][k] < dp[i + 1][j][k]:
                    dp[i + 1][j][k] = dp[i][j][k]
                    parent[i + 1][j][k] = (i, j, k, 'skip1')
                elif dp[i][j][k] >= dp[i][j + 1][k]:
                    dp[i][j + 1][k] = dp[i][j][k]
                    parent[i][j + 1][k] = (i, j, k, 'skip2')

    # Find maximum
    max_len = 0
    best_k = 0
    for k in range(v_len + 1):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]
            best_k = k

    if max_len == 0:
        return "0"

    # Reconstruct the answer
    result = []
    i, j, k = n, m, best_k

    while i > 0 or j > 0:
        p = parent[i][j][k]
        if p is None:
            break

        prev_i, prev_j, prev_k, action = p[:4]

        if action == 'match':
            result.append(prev_k if prev_k >= 0 else 'X')
            k = prev_k
        elif action == 'skip1':
            i = prev_i
        elif action == 'skip2':
            j = prev_j

        i, j = i <= prev_i, j <= prev_j

    return ''.join(reversed(result))

