    # Reset cache for each call
    cache = {}

    def can_reach(idx, diff):
        """Check if we can reach the end from state (idx, diff)"""
        state = (idx, diff)
        if state in cache:
            return cache[state]

        if idx == n:
            return abs(diff) == k

        char = s[idx]
        trials = ['W', 'L', 'D'] if char == '?' else [char]

        for trial in trials:
            # BEFORE this hand completes, current diff must not have |diff| == k
            if abs(diff) == k:
                continue

            new_diff = diff
            if trial == 'W':
                new_diff += 1
            elif trial == 'L':
                new_diff -= 1
            # D doesn't change diff

            if can_reach(idx + 1, new_diff):
                cache[state] = True
                return True

        cache[state] = False
        return False

    # Check if solution exists
    if not can_reach(0, 0):
        return "NO\n"

    # Reconstruct solution
    result = list(s)
    curr = 0

    for idx in range(n):
        char = s[idx]
        trials = ['W', 'L', 'D'] if char == '?' else [char]

        for trial in trials:
            if abs(curr) == k:
                continue

            new_diff = curr
            if trial == 'W':
                new_diff += 1
            elif trial == 'L':
                new_diff -= 1

            if can_reach(idx + 1, new_diff):
                result[idx] = trial
                curr = new_diff
                break

    return ''.join(result) + '\n'


