        # For nodes without cycles, compute actual GCD from all available cycles
        final_scc_gcd = []
        for scc_idx, nodes in enumerate(scc_nodes_list):
            if not nodes or len(nodes) <= 1:
                final_scc_gcd.append(0)
                continue

            start_node = nodes[0]
            dist = {start_node: 0}
            parent = {start_node: (None, 0, float('inf'))}
            stk = [start_node]
            gcd_val = 0
            edge_used = {}

            while stk:
                u = stk.pop()
                for v, w in adj[u]:
                    v_scc = scc_id.get(v, -1)
                    if v_scc == scc_idx:
